import{z as o,x as A,o as r,c as p,q as l,j as B,D as e,d as s,s as n,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"ECMP 与哈希","description":"","frontmatter":{"title":"ECMP 与哈希","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ecmp-hashing.md","filePath":"cs/ecmp-hashing.md","lastUpdated":1791063341000}'),d={name:"cs/ecmp-hashing.md"};function C(m,E,P,h,D,u){const t=A("Mermaid");return r(),p("div",null,[E[2]||(E[2]=l('<h1 id="ecmp-与哈希" tabindex="-1">ECMP 与哈希 <a class="header-anchor" href="#ecmp-与哈希" aria-label="Permalink to &quot;ECMP 与哈希&quot;">​</a></h1><div class="epigraph"><p>等代价多路径把流用五元组哈希钉到一条下一跳，保序且分流；极化发生在少量大象流撞上同一条边时。</p><footer>—— 据 RFC 2991 / 2992 多路径；RFC 6438 IPv6 流标签实践整理</footer></div><p><a href="/cs/segment-routing">上一课</a> 的前缀 SID 仍走 ECMP。主干 OSPF 已点名等代价。<a href="/cs/lacp">LACP</a> 在二层哈希。缺口是<strong>三层哈希怎么键、为何不保带宽公平</strong>。本课不把 VXLAN 封装写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TE 可以钉路径；默认 IGP 给多条等代价下一跳。逐包喷洒会乱序，TCP 当成丢包。故按流哈希：同四元组（再加流标签）同路径。极化：哈希空间均匀不等于流量均匀——BDP 大的几条流可打满一条 100G，其它边空。重哈希（链路 up/down）会移动流，造成瞬时乱序。</p><p><span class="marginnote">数字实例：一条 40 Gbps 的大象流被哈希钉到某条 100G 边上；若再来两条同类流恰好都撞上同一条边，120 Gbps 就把这条边打满丢包，而其余三条等价边可能近乎空转。哈希函数本身完全均匀——问题不在偏置，在流大小不均。</span></p><p>不要把 ECMP 当成 WFQ：没有按流排队保证。</p><p><span class="marginnote">术语翻译：WFQ（加权公平排队）是按流排队、按权重分带宽的调度机制；ECMP 只回答「这条流走哪条路」，完全不排队、不承诺公平份额。把两者混为一谈，会误以为开了 ECMP 带宽就自动均分。</span></p><p><span class="marginnote">RFC 2991。数据中心后课 Clos 依赖大量 ECMP。本课不把具体 CRC 多项式当标准。</span></p><h3 id="保序不保公平" tabindex="-1">保序不保公平 <a class="header-anchor" href="#保序不保公平" aria-label="Permalink to &quot;保序不保公平&quot;">​</a></h3><p>按流哈希避免乱序；大象流极化。隧道要把熵透传到外层。重哈希会瞬时乱序。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 LACP 键与 ECMP 键：一层 vs 三层，对象都是保序分流。画：候选下一跳集合 → 哈希 → 一条。对称性：正向与反向哈希不一致会导致不对称路径，排障痛苦，不是错误。</p>',13)),(r(),B(i,null,{default:e(()=>[n(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E7%AD%89%E4%BB%A3%E4%BB%B7%E4%B8%8B%E4%B8%80%E8%B7%B3%E9%9B%86%22%5D%20--%3E%20H%5B%22%E4%BA%94%E5%85%83%E7%BB%84%E5%93%88%E5%B8%8C%22%5D%0A%20%20H%20--%3E%20ONE%5B%22%E4%B8%80%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%0A%20%20EL%5B%22%E5%A4%A7%E8%B1%A1%E6%B5%81%22%5D%20--%3E%20POL%5B%22%E6%9E%81%E5%8C%96%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[s("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"MPLS 可用熵标签把内层熵露给外层哈希，避免全网只按外层标签极化。VXLAN 后课同样要把内层端口映到 UDP 源端口。交换机 HOL：多条 ECMP 仍可能在某一跳汇聚到同一出端口。RPKI 与哈希无关。",-1)),E[5]||(E[5]=a("p",null,"随机化种子：不同设备用不同密钥防攻击者构造碰撞打满一条，是安全边注。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"这条防的是定向拥塞攻击：若全网用同一个哈希密钥，攻击者可以离线构造一批五元组恰好全撞上同一条链路；每台设备密钥不同，异地预制好的碰撞就失效了。直觉类比：各班用不同的打乱规则排座位，外面的人没法照抄一份名单预测谁挨着谁。")],-1)),E[7]||(E[7]=a("p",null,"隧道里内层五元组各不相同，为什么外层看不见就分流失效？",-1)),(r(),B(i,null,{default:e(()=>[n(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKT%5B%22%E5%86%85%E5%B1%82%E5%8C%85%EF%BC%9A%E7%AB%AF%E5%8F%A3%E5%90%84%E4%B8%8D%E7%9B%B8%E5%90%8C%22%5D%20--%3E%20TUN%5B%22%E5%85%A8%E9%83%A8%E5%B0%81%E8%BF%9B%E5%90%8C%E4%B8%80%E6%9D%A1%E9%9A%A7%E9%81%93%22%5D%0A%20%20TUN%20--%3E%20OUTER%5B%22%E5%A4%96%E5%B1%82%E5%8F%AA%E6%9C%89%E5%90%8C%E4%B8%80%E4%B8%AA%E4%BA%94%E5%85%83%E7%BB%84%22%5D%0A%20%20OUTER%20--%3E%20H1%5B%22%E5%A4%96%E5%B1%82%E5%93%88%E5%B8%8C%E8%BE%93%E5%85%A5%E7%9B%B8%E5%90%8C%22%5D%0A%20%20H1%20--%3E%20ONE%5B%22%E6%95%B4%E6%9D%A1%E9%9A%A7%E9%81%93%E6%8C%A4%E4%B8%8A%E5%90%8C%E4%B8%80%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%0A%20%20TUN%20--%3E%20ENT%5B%22%E7%86%B5%E6%A0%87%E7%AD%BE%2F%E5%A4%96%E5%B1%82%E6%BA%90%E7%AB%AF%E5%8F%A3%E5%B8%A6%E4%B8%8A%E5%86%85%E5%B1%82%E7%86%B5%22%5D%0A%20%20ENT%20--%3E%20H2%5B%22%E5%A4%96%E5%B1%82%E5%93%88%E5%B8%8C%E8%BE%93%E5%85%A5%E9%9A%8F%E6%B5%81%E5%8F%98%E5%8C%96%22%5D%0A%20%20H2%20--%3E%20MANY%5B%22%E8%83%BD%E5%88%86%E5%88%B0%E5%A4%9A%E6%9D%A1%E7%AD%89%E4%BB%B7%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入动态负载均衡（packet spraying with reordering repair）的全部。VXLAN 与覆盖网是下一课。后课默认：ECMP = 保序哈希，不保证流量公平。</p><p>不等代价分流（UCMP）按权重，仍是哈希，不是 TE 约束求解。</p><p>下一课<a href="/cs/vxlan-overlay">VXLAN 与覆盖网</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>按流哈希保序，按包喷洒乱序。</li><li>极化来自流大小，不是哈希偏置的唯一原因。</li><li>熵要透传到外层才能在隧道上 ECMP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2991；RFC 6438。</li></ul>',6))])}const f=o(d,[["render",C]]);export{T as __pageData,f as default};
